 for key in ['fields','nodes','text']:u(len(d[key]));[text(x)for x in d[key]]
 u(len(d['states']));q(*d['states']);u(len(d['numbers']));f(*d['numbers']);q(d['manual']);u(len(d['modes']))
 for m in d['modes']:q(m['id']);f(m['acceleration'],m['cap'],m['takeoff'],m['multiplier'])
 for n in d['names']:text(n)
